export class Queue<T> {
    private data: T[] = [];

    get length(): number {
        return this.data.length;
    }

    get isEmpty(): boolean {
        return this.data.length === 0;
    }

    public enqueue(item: T): void {
        this.data.push(item);
    }

    public dequeue(): T | undefined {
        return this.data.shift();
    }

    public peek(): T | undefined {
        return this.data[0];
    }

    public clear(): void {
        this.data.length = 0;
    }
}
